package com.finsightai.controller;import com.finsightai.dto.*;import com.finsightai.service.AnalyticsService;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/analytics") public class AnalyticsController{private final AnalyticsService a;public AnalyticsController(AnalyticsService a){this.a=a;}@GetMapping("/anomalies")public List<AnomalyResponse> anomalies(){return a.anomalies();}@GetMapping("/forecast")public List<ForecastPoint> forecast(@RequestParam(defaultValue="3")int months){return a.forecast(Math.min(Math.max(months,1),12));}}
